"""Render the Heracles schema as an OpenLDAP ``.schema`` file or a ``cn=config`` LDIF."""

from __future__ import annotations

from collections.abc import Iterable, Iterator

from heracles.schema.definitions import ATTRIBUTE_TYPES, OBJECT_CLASSES
from heracles.schema.model import AttributeType, ObjectClass

SCHEMA_NAME = "heracles"
_HEADER = (
    "Heracles LDAP schema. Generated by `heracles schema export`; do not edit by hand.",
    "Source: backend/src/heracles/schema/definitions.py",
)


def _names(values: Iterable[str]) -> str:
    items = list(values)
    if len(items) == 1:
        return items[0]
    return "( " + " $ ".join(items) + " )"


def attribute_definition(attr: AttributeType) -> str:
    """RFC 4512 ``AttributeTypeDescription`` of ``attr``."""
    parts = [f"( {attr.oid}", f"NAME '{attr.name}'"]
    if attr.desc:
        parts.append(f"DESC '{attr.desc}'")
    parts.append(f"EQUALITY {attr.syntax.equality}")
    if attr.syntax.ordering:
        parts.append(f"ORDERING {attr.syntax.ordering}")
    if attr.syntax.substr:
        parts.append(f"SUBSTR {attr.syntax.substr}")
    parts.append(f"SYNTAX {attr.syntax.oid}")
    if attr.single:
        parts.append("SINGLE-VALUE")
    return " ".join(parts) + " )"


def object_class_definition(cls: ObjectClass) -> str:
    """RFC 4512 ``ObjectClassDescription`` of ``cls``."""
    parts = [f"( {cls.oid}", f"NAME '{cls.name}'"]
    if cls.desc:
        parts.append(f"DESC '{cls.desc}'")
    parts.extend([f"SUP {cls.sup}", cls.kind])
    if cls.must:
        parts.append(f"MUST {_names(cls.must)}")
    if cls.may:
        parts.append(f"MAY {_names(cls.may)}")
    return " ".join(parts) + " )"


def render_schema() -> str:
    """OpenLDAP ``.schema`` text (``attributetype`` / ``objectclass`` statements)."""
    lines = [f"# {line}" for line in _HEADER]
    lines.append("")
    lines.extend(f"attributetype {attribute_definition(a)}" for a in ATTRIBUTE_TYPES)
    lines.append("")
    lines.extend(f"objectclass {object_class_definition(c)}" for c in OBJECT_CLASSES)
    return "\n".join(lines) + "\n"


def _fold(line: str, width: int = 76) -> Iterator[str]:
    """LDIF line folding (RFC 2849): continuation lines start with one space."""
    yield line[:width]
    rest = line[width:]
    while rest:
        yield " " + rest[: width - 1]
        rest = rest[width - 1 :]


def render_ldif() -> str:
    """``cn=config`` schema entry loadable with ``ldapadd -Y EXTERNAL -H ldapi:///``."""
    lines = [f"# {line}" for line in _HEADER]
    lines.extend(
        [
            f"dn: cn={SCHEMA_NAME},cn=schema,cn=config",
            "objectClass: olcSchemaConfig",
            f"cn: {SCHEMA_NAME}",
        ]
    )
    for attr in ATTRIBUTE_TYPES:
        lines.extend(_fold(f"olcAttributeTypes: {attribute_definition(attr)}"))
    for cls in OBJECT_CLASSES:
        lines.extend(_fold(f"olcObjectClasses: {object_class_definition(cls)}"))
    return "\n".join(lines) + "\n"
